<include file="Public:header"/><div class="mainbox">    <div id="nav" class="mainnav_title">        <ul>            <a href="{pigcms{:U('User/spread_mer_list')}" class="on"><if condition="$now_user">【{pigcms{$now_user['nickname']}】<else />用户</if>推广商家列表</a>        </ul>    </div>    <table class="search_table" width="100%">        <tr>            <td>                <form action="{pigcms{:U('User/user_spread_list')}" method="get">                    <input type="hidden" name="c" value="User"/>                    <input type="hidden" name="a" value="user_spread_list"/>                    筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>                    <select name="searchtype">                        <option value="uid" <if condition="$_GET['searchtype'] eq 'uid'">selected="selected"</if>>用户ID</option>                        <option value="nickname" <if condition="$_GET['searchtype'] eq 'nickname'">selected="selected"</if>>昵称</option>                        <option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>手机号</option>                    </select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                    <font color="#000">注册日期筛选：</font>                    <input type="text" class="input-text" name="begin_time" style="width:120px;" id="d4311"  value="{pigcms{$_GET.begin_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                    <input type="text" class="input-text" name="end_time" style="width:120px;" id="d4311" value="{pigcms{$_GET.end_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                    状态:                    <select name="status">                        <option value="" <if condition="$_GET['status'] eq ' '">selected="selected"</if>>全部</option>                        <option value="1" <if condition="$_GET['status'] eq '1'">selected="selected"</if>>正常</option>                        <option value="0" <if condition="$_GET['status'] eq '0'">selected="selected"</if>>禁用</option>                    </select>                    <input type="submit" style="margin-right:20px;" value="查询" class="button"/>                </form>            </td>        </tr>    </table>    <form name="myform" id="myform" action="" method="post">        <div class="table-list">            <table width="100%" cellspacing="0">                <colgroup>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col width="180" align="center"/>                </colgroup>                <thead>                <tr>                    <th>ID</th>                    <th>商家名称</th>                    <th>手机号</th>                    <th>最后登录时间</th>                    <th>最后登录地址</th>                    <th class="textcenter">商家余额</th>                    <th class="textcenter">状态</th>                    <th class="textcenter">获得的推广佣金</th>                </tr>                </thead>                <tbody>                <if condition="is_array($mers['mer_list'])">                    <volist name="mers['mer_list']" id="vo">                        <tr>                            <td>{pigcms{$vo.mer_id}</td>                            <td>{pigcms{$vo.name}</td>                            <td>{pigcms{$vo.phone}</td>                            <td>{pigcms{$vo.last_time|date='Y-m-d H:i:s',###}</td>                            <td>{pigcms{$vo.last_ip_txt}</td>                            <td class="textcenter">{pigcms{$config['Currency_symbol']}{pigcms{$vo.money|floatval=###}</td>                            <td class="textcenter"><if condition="$vo['status'] eq 1"><font color="green">正常</font><elseif condition="$vo['status'] eq 2" /><font color="red">审核中</font><else /><font color="red">禁用</font></if></td>                            <td class="textcenter">{pigcms{$config['Currency_symbol']}{pigcms{$vo['s_money']}</td>                        </tr>                    </volist>                    <tr><td class="textcenter pagebar" colspan="12">{pigcms{$mers['pagebar']}</td></tr>                    <else/>                    <tr><td class="textcenter red" colspan="12">列表为空！</td></tr>                </if>                </tbody>            </table>        </div>    </form></div><include file="Public:footer"/>